:root {
  --bg: #1a1c2c;
  --card: #2b2d42;
  --text: #f0f0f0;
  --accent: #ffcd75;
  --accent-dark: #e0a800;
  --danger: #ef476f;
  --border: #5a5e7a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 3px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 8px 0 rgba(0,0,0,0.3);
}

h1 {
  margin: 0 0 20px;
  font-size: 1.8rem;
  letter-spacing: 1px;
  color: var(--accent);
  text-align: center;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}

#todo-input {
  flex: 1;
  padding: 12px;
  font-size: 1rem;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  outline: none;
}

#todo-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255,205,117,0.3);
}

button {
  font-size: 1rem;
  font-family: inherit;
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: var(--bg);
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.1s, background 0.2s;
}

button:hover { background: var(--accent-dark); }
button:active { transform: translateY(2px); }
button:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

.counts {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  font-size: 1.1rem;
  color: var(--text);
}

.counts strong { color: var(--accent); font-size: 1.3rem; }

.todo-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 12px;
}

.todo-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}

.todo-text {
  flex: 1;
  word-break: break-word;
  font-size: 1rem;
}

.todo-item.done .todo-text {
  text-decoration: line-through;
  opacity: 0.6;
}

.todo-delete {
  background: transparent;
  color: var(--danger);
  font-size: 1.2rem;
  padding: 4px 10px;
  border: 2px solid transparent;
  border-radius: 6px;
}

.todo-delete:hover { background: rgba(239,71,111,0.15); }
.todo-delete:focus-visible { outline: 2px solid var(--danger); outline-offset: 2px; }

.empty {
  text-align: center;
  color: var(--border);
  font-style: italic;
  margin: 16px 0 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.4rem; }
  .input-row { flex-direction: column; }
  #todo-add { width: 100%; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');
const emptyMsg = document.getElementById('empty-msg');
const form = document.getElementById('todo-form');

let tasks = [];
let nextId = 1;

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
  emptyMsg.style.display = tasks.length ? 'none' : 'block';
}

function renderTask(task) {
  const li = document.createElement('li');
  li.className = 'todo-item' + (task.done ? ' done' : '');
  li.dataset.id = task.id;

  const check = document.createElement('input');
  check.type = 'checkbox';
  check.id = 'todo-check-' + task.id;
  check.checked = task.done;
  check.setAttribute('aria-label', 'Mark "' + task.text + '" as complete');
  check.addEventListener('change', () => {
    task.done = check.checked;
    li.classList.toggle('done', task.done);
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = 'todo-text-' + task.id;
  span.className = 'todo-text';
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.id = 'todo-delete-' + task.id;
  del.className = 'todo-delete';
  del.textContent = '✕';
  del.setAttribute('aria-label', 'Delete "' + task.text + '"');
  del.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  const label = document.createElement('label');
  label.htmlFor = check.id;
  label.className = 'sr-only';
  label.textContent = 'Complete task: ' + task.text;

  li.append(check, label, span, del);
  list.appendChild(li);
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  renderTask(task);
  input.value = '';
  input.focus();
  updateCounts();
}

form.addEventListener('submit', e => { e.preventDefault(); addTask(); });
addBtn.addEventListener('click', addTask);
updateCounts();
